import { cookies } from 'next/headers';

export default async function Page() {
  const session = (await cookies()).get('session');
  const data = await fetch('/api/user', { cache: 'no-store' }).then(r => r.json());
  return <Dashboard user={data} />;
}

export default async function Page({ params }) {
  const product = await fetch(`/api/products/${params.id}`).then(r => r.json());
  return <ProductPage product={product} />;
}

export default async function Page({ searchParams }) {
  const q = (await searchParams).q;
  const results = await fetch(`/api/search?q=${q}`).then(r => r.json());
  return <SearchResults items={results} />;
}

import { Suspense } from 'react';

export default async function Page({ params }) {
  const product = await fetch(`/products/${params.id}`, {
    next: { revalidate: 3600 }
  }).then(r => r.json());

  return (
    <div>
      <ProductInfo product={product} />
      <Suspense fallback={<Spinner />}>
        <Recommendations productId={params.id} />
      </Suspense>
    </div>
  );
}

